beforeEach(async function () {
    [owner, addr1, addr2, bridgeOperator] = await ethers.getSigners();

    // Deploy contract with 1M initial supply
    initialSupply = ethers.parseUnits("1000000", DECIMALS);

    const WRTC = await ethers.getContractFactory("WRTC");
    wrtc = await WRTC.deploy(initialSupply, bridgeOperator.address);
    await wrtc.waitForDeployment();
  })

beforeEach(() => {
  jest.clearAllMocks();
  useAuth.mockReturnValue({ user: { token: "tok" } });
  api.get.mockImplementation((path) => {
    if (path === "/tools/agent") return Promise.resolve([{ name: "calculator" }]);
    if (path === "/projects/3") return Promise.resolve(PROJECT);
    if (path === "/projects") return Promise.resolve({ projects: [] });
    if (path === "/projects/3/custom-tools") return Promise.resolve({ tools: [] });
    if (path === "/llms") {
      return Promise.resolve({ llms: [{ name: "gpt-main" }, { name: "backup-llm" }] });
    }
    return Promise.resolve({});
  });
  api.patch.mockResolvedValue({});
})

