    const helperMax = Math.max(...benchmarkResults.helpers);
    console.log(`  Average: ${helperAvg.toFixed(2)}ms`);
    console.log(`  Max: ${helperMax.toFixed(2)}ms`);
    console.log(`  Target: <100ms - ${helperAvg < 100 ? '✓ PASS' : '✗ FAIL'}\n`);

    console.log('======================================\n');
  })

