after(function () {
    if (!run) return;
    // Print summary
    var pass = 0;
    var fail = 0;
    var notRun = 0;
    var failures = [];

    ALL_TESTS.forEach(function (test) {
      var result = run.results[test.addr];
      if (result === 0x01) {
        pass++;
      } else if (result === 0x00 || result === 0xff) {
        notRun++;
      } else {
        fail++;
        failures.push(
          "    " + test.page + " / " + test.name + ": " + formatResult(result),
        );
      }
    });

    console.log("");
    console.log(
      "    AccuracyCoin: " +
        pass +
        " passed, " +
        fail +
        " failed, " +
        notRun +
        " not run (" +
        run.framesRun +
        " frames)",
    );
    if (failures.length > 0) {
      console.log("    Failures:");
      failures.forEach(function (f) {
        console.log(f);
      });
    }
  })

