before(async () => {
		pngData = await readFile(join(FIXTURES_DIR, "smiley.png"));

		server = http.createServer((req, res) => {
			switch (req.url) {
				case "/smiley.png":
				case "/my%20smiley.png":
					res.writeHead(200, { "content-type": "image/png" });
					res.end(pngData);
					break;

				case "/no-content-type":
					res.writeHead(200);
					res.end(pngData);
					break;

				case "/chunked.png":
					// no content-length, so the size can only be known by reading
					res.writeHead(200, { "content-type": "image/png" });
					res.write(pngData);
					res.end(pngData);
					break;

				case "/page.html":
					res.writeHead(200, { "content-type": "text/html" });
					res.end("<html></html>");
					break;

				case "/photo.webp":
					res.writeHead(200, { "content-type": "image/webp" });
					res.end(WEBP_DATA);
					break;

				case "/mislabeled.png":
					res.writeHead(200, { "content-type": "image/png" });
					res.end(WEBP_DATA);
					break;

				case "/empty.png":
					res.writeHead(200, {
						"content-type": "image/png",
						"content-length": "0",
					});
					res.end();
					break;

				case "/slow.png":
					// never respond
					break;

				default:
					res.writeHead(404, { "content-type": "image/png" });
					res.end("Not Found");
			}
		});

		await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
		const address = /** @type {import("node:net").AddressInfo} */ (
			server.address()
		);
		baseUrl = `http://127.0.0.1:${address.port}`;
	})

after(done => {
		/*
		 * Stop listening, then drop the connection left open by the timeout
		 * test so the close callback fires. Bun stops the server when its
		 * connections are closed and then reports "Server is not running"
		 * to the callback, so ignore any error.
		 */
		server.close(() => done());
		server.closeAllConnections();
	})

