  fs.writeFileSync(
    path.join(subDir, `agent-${SUB_ID}.jsonl`),
    [
      {
        type: "user",
        sessionId: SESSION,
        timestamp: "2026-04-18T12:00:00.000Z",
        message: { content: "go" },
      },
      {
        type: "assistant",
        sessionId: SESSION,
        timestamp: "2026-04-18T12:00:05.000Z",
        message: {
          model: SUB_MODEL,
          content: [{ type: "text", text: "ok" }],
          usage: { input_tokens: 2_000_000, output_tokens: 1_000_000 },
        },
